<template><Card class="s1-ui s1-compact-list s1-category-page"><header class="ui-header"><div><h2>商品分类</h2></div><Button type="primary" :disabled="blocked" @click="edit(null)">添加一级分类</Button></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><div class="ui-search"><label>类目名称／路径<Input v-model="queryDraft" placeholder="搜索叶子名称，保留祖先路径" @on-enter="search"/></label><label>自身启停状态<Select v-model="stateDraft" clearable><Option value="true">启用</Option><Option value="false">停用</Option></Select></label><div class="ui-actions"><Button type="primary" @click="search">查询</Button><Button @click="reset">重置</Button></div></div><div class="ui-toolbar"><span>共 {{catalogRecords.length}} 个分类；点击分类名前的箭头查看下级</span><Button @click="reload">刷新</Button></div><Table class="s1-list-table" v-compact-table row-key="id" update-show-children :data="treeRows" :columns="columns" :loading="loading" @on-expand-tree="expandedTree" no-data-text="没有符合条件的类目"><template slot="state" slot-scope="{row}"><i-switch :key="row.id+':'+switchEpoch" size="large" :value="row.enabled" :disabled="blocked||!!switchingId" :loading="busy&&switchingId===row.id" @on-change="toggle(row)"><span slot="open">开启</span><span slot="close">关闭</span></i-switch><span v-if="row.contextOnly" class="ui-meta"> · 祖先上下文</span><span v-else-if="row.enabled&&!effective(row)" class="ui-meta"> · 父级已停用</span></template><template slot="qualification" slot-scope="{row}">{{row.qualificationTypes.map(status).join('、')||'未配置专项要求'}}</template><template slot="operations" slot-scope="{row}"><div class="s1-native-ops"><button class="ui-link" :disabled="blocked" @click="edit(row)">编辑</button><template v-if="row.level<3"><Divider type="vertical"/><button class="ui-link" :disabled="blocked" @click="edit(null,row)">添加子分类</button></template><Divider type="vertical"/><button class="ui-link" @click="history(row)">影响与历史</button></div></template></Table><Modal v-model="show" :title="editing?'编辑类目':'新增类目'" width="780" :mask-closable="false" :closable="!busy" footer-hide><div class="s1-ui"><Form ref="form" :model="form" :rules="rules" :label-width="125" class="ui-form"><FormItem label="类目名称" prop="name"><Input v-model="form.name" maxlength="30" :disabled="blocked"/></FormItem><FormItem label="父级类目"><Cascader :data="parents" :value="parentPath" change-on-select :disabled="blocked||parentLocked" @on-change="chooseParent"/><p class="ui-note">{{parentLocked?'该类目已有商品引用或子级，父级不可搬移。':'不显示自身、后代或第三级父节点。'}}新类目默认停用。</p></FormItem><FormItem label="排序"><InputNumber v-model="form.sort" :min="0" :max="9999" :precision="0" :disabled="blocked"/></FormItem><FormItem label="必需专项资质"><Select v-model="form.qualificationTypes" multiple :disabled="blocked"><Option v-for="v in qualificationTypes" :key="v.code" :value="v.code">{{status(v.code)}}</Option></Select><p class="ui-note">缺少真实业务资质清单的新增公共类目保持停用。</p></FormItem><FormItem label="变更原因" prop="reason"><Input v-model="form.reason" type="textarea" :rows="3" maxlength="500" :disabled="blocked"/></FormItem></Form><p v-if="error" class="ui-error">{{error}}</p><footer class="ui-form-footer"><Button :disabled="busy" @click="show=false;dirty=false">取消</Button><Button type="primary" :loading="busy" :disabled="pending" @click="save">保存类目</Button></footer></div></Modal><Drawer v-model="historyShow" title="类目影响与版本历史" width="85"><div v-if="selected" class="s1-ui"><h2>{{selected.item.name}}</h2><p class="ui-meta">{{selected.item.id}} · 策略 v{{selected.item.version}}</p><HistoryTable :records="selected.history.map(h=>({...h,name:h.snapshot.name,enabledText:h.snapshot.enabled?'启用':'停用',parentName:pathFor(h.snapshot.parentId)}))" :columns="historyColumns"/><DetailSection title="当前引用影响" :grid="false" description="只展示当前影响；历史商品和已批准快照不会被重写。"><h3>商户（{{selected.impact.storeTotal}}）</h3><Table :data="storeImpact" :columns="storeColumns" no-data-text="暂无受影响商户"/><Page class="ui-pagination" :total="selected.impact.storeTotal" :current="storePage" :page-size="20" @on-change="storePage=$event;impact('store')"/><h3>商品（{{selected.impact.goodsTotal}}）</h3><Table :data="goodsImpact" :columns="goodsColumns" no-data-text="暂无受影响商品"/><Page class="ui-pagination" :total="selected.impact.goodsTotal" :current="goodsPage" :page-size="20" @on-change="goodsPage=$event;impact('goods')"/></DetailSection></div></Drawer></Card></template>
<script>import page from './page';import display from './display.cjs';import demo from './demo-data.cjs';import PageStatus from './components/PageStatus';import HistoryTable from './components/HistoryTable';import DetailSection from './components/DetailSection';export default {mixins:[page],components:{PageStatus,HistoryTable,DetailSection},data:()=>({switchingId:null,switchEpoch:0,formBaseline:'',queryDraft:'',stateDraft:'',query:'',enabled:'',expanded:[],show:false,historyShow:false,editing:null,form:{name:'',parentId:'0',sort:0,qualificationTypes:[],reason:''},qualificationTypes:[],storePage:1,goodsPage:1,storeImpact:[],goodsImpact:[],historyTicket:0,rules:{name:[{required:true,message:'请填写1～30字类目名称',trigger:'blur'}],reason:[{required:true,message:'请填写变更原因',trigger:'blur'}]},columns:[{title:'分类名称',key:'name',tree:true,minWidth:260},{title:'状态',slot:'state',minWidth:180},{title:'排序',key:'sort',width:70},{title:'必需专项资质',slot:'qualification',minWidth:170},{title:'商品引用',key:'referencedGoods',width:95},{title:'操作',slot:'operations',minWidth:260}],historyColumns:[{title:'版本',key:'version',width:80},{title:'名称',key:'name',minWidth:150},{title:'父级（当前名称）',key:'parentName',minWidth:180},{title:'状态',key:'enabledText',width:100},{title:'原因',key:'reason',minWidth:180},{title:'时间',slot:'time',minWidth:180}],storeColumns:[{title:'店铺',key:'storeName',minWidth:180},{title:'编号',key:'storeId',minWidth:180},{title:'版本',key:'version',width:80}],goodsColumns:[{title:'商品',key:'name',minWidth:180},{title:'编号',key:'id',minWidth:180},{title:'审核状态',key:'reviewStatus',minWidth:130}]}),watch:{form:{deep:true,handler(value){if(this.show)this.dirty=JSON.stringify(value)!==this.formBaseline;}}},computed:{catalogRecords(){return this.demoActive?demo.categoryRows(this.records,false):this.records;},treeRows(){return display.tree(this.catalogRecords,{query:this.query,enabled:this.enabled,expanded:this.expanded});},parentLocked(){return this.editing&&(this.editing.referencedGoods>0||this.records.some(r=>r.parentId===this.editing.id));},parents(){const rows=display.parentOptions(this.catalogRecords,this.editing&&this.editing.id).map(r=>({...r,value:r.id,label:r.name}));return [{value:'0',label:'顶级类目'},...display.tree(rows).map(this.cascade)];},parentPath(){if(this.form.parentId==='0')return ['0'];let value=this.records.find(r=>r.id===this.form.parentId);const path=[];for(let i=0;value&&i<3;i++){path.unshift(value.id);value=this.records.find(r=>r.id===value.parentId);}return path;}},mounted(){this.query=this.$route.query.q||'';this.queryDraft=this.query;this.enabled=this.$route.query.enabled||'';this.stateDraft=this.enabled;try{this.expanded=JSON.parse(sessionStorage.getItem('s1-ui-category-expanded-v2')||'[]');}catch(_){this.expanded=[];}this.reload();},beforeDestroy(){this.historyTicket++;},methods:{cascade(row){return {value:row.id,label:row.name,children:row.children.map(this.cascade)};},chooseParent(values){this.form.parentId=values.length?String(values[values.length-1]):'0';},effective(row){let current=row;for(let i=0;current&&i<3;i++){if(!current.enabled)return false;current=this.records.find(r=>r.id===current.parentId);}return true;},pathFor(id){if(!id||id==='0')return '顶级类目';const node=this.records.find(r=>r.id===id);return node?node.name:'名称未提供（'+id+'）';},reload(){return this.latest(()=>Promise.all([this.read('/categories'),this.read('/qualification-types')]),([rows,types])=>{this.records=rows;if(!sessionStorage.getItem('s1-ui-category-expanded-v2')&&!this.expanded.length)this.expanded=this.catalogRecords.filter(r=>r.level===1).map(r=>r.id);this.qualificationTypes=types.filter(t=>t.scope==='CATEGORY'&&t.enabled);});},search(){this.query=this.queryDraft;this.enabled=this.stateDraft||'';this.$router.replace({path:'/s1/categories',query:{q:this.query,enabled:this.enabled,...(this.demoAvailable?{showTests:this.showTestData?'1':'0'}:{})}});},reset(){this.queryDraft='';this.stateDraft='';this.search();},expandedTree(rowKey,expanded){this.expanded=demo.expandedIds(this.expanded,rowKey,expanded);this.saveExpanded();},saveExpanded(){sessionStorage.setItem('s1-ui-category-expanded-v2',JSON.stringify(this.expanded));},edit(row,parent){this.error='';this.editing=row;this.form={name:row?row.name:'',parentId:row?row.parentId:parent?parent.id:'0',sort:row?row.sort:0,qualificationTypes:row?[...row.qualificationTypes]:[],reason:''};if(parent){this.expanded=[...new Set([...this.expanded,parent.id])];this.saveExpanded();}this.formBaseline=JSON.stringify(this.form);this.dirty=false;this.show=true;this.dirty=false;},save(){this.$refs.form.validate(async valid=>{if(!valid)return;try{const result=await this.run('/categories'+(this.editing?'/'+this.editing.id:''),{...this.form,...(this.editing?{expectedVersion:this.editing.version}:{})},this.editing?'PUT':'POST');if(result){this.show=false;await this.reload();this.$nextTick(()=>{const row=document.querySelector('[data-row-key="'+result.id+'"]');if(row)row.scrollIntoView({block:'center'});});}}catch(_){}});},async toggle(row){if(this.switchingId)return;this.switchingId=row.id;try{const result=await this.command('/categories/'+row.id+(row.enabled?'/disable':'/enable'),row.enabled?'停用类目':'启用类目',{expectedVersion:row.version},row.name+'。'+(row.enabled?'后代新业务可用性同时受限，后代自身状态和历史引用不改写。':'父级及必要资质策略仍须满足，启用不扩大任何商户范围。'));if(result)await this.reload();}finally{this.switchingId=null;this.switchEpoch++;}},async history(row){const ticket=++this.historyTicket;this.error='';this.selected=null;this.historyShow=true;this.storePage=1;this.goodsPage=1;try{const value=await this.read('/categories/'+row.id,{pageNumber:1,pageSize:20});if(ticket===this.historyTicket){this.selected=value;this.storeImpact=value.impact.stores;this.goodsImpact=value.impact.goods;}}catch(e){if(ticket===this.historyTicket)this.error=e.message;}},async impact(type){const id=this.selected.item.id,ticket=++this.historyTicket;try{const v=await this.read('/categories/'+id,{pageNumber:type==='store'?this.storePage:this.goodsPage,pageSize:20});if(ticket===this.historyTicket&&this.selected&&id===this.selected.item.id){if(type==='store')this.storeImpact=v.impact.stores;else this.goodsImpact=v.impact.goods;}}catch(e){if(ticket===this.historyTicket)this.error=e.message;}}}};</script>
